  it('IMP05-PHASE-05 · Respuestas tardías, cambio de cuenta y revocación → no reemplazan datos vigentes ni revelan datos pedagógicos', () => {
    prepare('capacity').then((c) => {
      let failureChecksActive = true;
      let organizationUnavailable = true;
      let dashboardDenied = false;
      let requestStage = 'initial';
      let releaseOrganizationError: (() => void) | undefined;
      let releaseDashboardError: (() => void) | undefined;
      const requestCounts: Record<string, number> = {};
      const failure = (status: 503 | 403) => ({
        statusCode: status,
        body: {
          error: {
            code: status === 503 ? 'PERSISTENCE_UNAVAILABLE' : 'FORBIDDEN',
            message: 'La consulta no está disponible.',
            retryable: status === 503,
            fields: [],
          },
          requestId: 'c5050000-0000-4000-8000-000000000001',
        },
      });
      function holdFailure(
        reply: () => void,
        capture: (release: () => void) => void,
      ) {
        return new Cypress.Promise<void>((resolve) => {
          let released = false;
          const release = () => {
            if (released) return;
            released = true;
            reply();
            resolve();
          };
          capture(release);
          releases.push(release);
        });
      }
      cy.intercept(
        {
          method: 'GET',
          pathname: `/api/v1/organizations/${c.organizationId}`,
        },
        (request) => {
          if (!failureChecksActive || new URL(request.url).searchParams.size)
            return request.continue();
          const alias = `organizationGate${requestStage}`;
          request.alias = alias;
          requestCounts[alias] = (requestCounts[alias] ?? 0) + 1;
          if (organizationUnavailable)
            return holdFailure(
              () => request.reply(failure(503)),
              (release) => {
                releaseOrganizationError = release;
              },
            );
          request.continue();
        },
      );
      cy.intercept(
        {
          method: 'GET',
          pathname: `/api/v1/classes/${c.classroomId}/dashboard`,
        },
        (request) => {
          if (!failureChecksActive || new URL(request.url).searchParams.size)
            return request.continue();
          const alias = `dashboardGate${requestStage}`;
          request.alias = alias;
          requestCounts[alias] = (requestCounts[alias] ?? 0) + 1;
          if (dashboardDenied)
            return holdFailure(
              () => request.reply(failure(403)),
              (release) => {
                releaseDashboardError = release;
              },
            );
          request.continue();
        },
      );
      for (const cycle of [0, 1]) {
        const blocked = `Blocked${cycle}`;
        const retried = `Retried${cycle}`;
        cy.then(() => {
          requestStage = blocked;
          organizationUnavailable = true;
          dashboardDenied = false;
          releaseOrganizationError = undefined;
          releaseDashboardError = undefined;
        });
        visitAs(c.teacher, route(c, 'dashboard'));
        cy.wait(`@dashboardGate${blocked}`).then(({ response }) => {
          expect(response!.statusCode).to.equal(200);
          expect(response!.body.data.summary).to.include({
            completed: c.oracle.completed,
            required: c.oracle.required,
          });
          expect(response!.body.data.summary.period.attempts).to.equal(
            c.oracle.attempts,
          );
        });
        cy.get('[data-cy="dashboard-summary"]').should('not.exist');
        cy.get('[data-cy="dashboard-student-row"]').should('not.exist');
        cy.wrap(null).should(() =>
          expect(releaseOrganizationError).to.be.a('function'),
        );
        cy.then(() => releaseOrganizationError!());
        cy.wait(`@organizationGate${blocked}`)
          .its('response.statusCode')
          .should('equal', 503);
        cy.contains('[role="alert"]', 'Consulta no disponible').should(
          'be.visible',
        );
        cy.get('[data-cy="dashboard-summary"]').should('not.exist');
        cy.then(() => {
          requestStage = retried;
          organizationUnavailable = false;
          dashboardDenied = cycle === 1;
        });
        cy.contains('button', 'Reintentar consulta').click();
        cy.wait(`@organizationGate${retried}`).then(({ response }) => {
          expect(response!.statusCode).to.equal(200);
          expect(response!.body.data.id).to.equal(c.organizationId);
        });
        if (cycle === 1) {
          // The fresh organization must not expose the earlier successful
          // dashboard while its renewed permission check is still pending.
          cy.get('[data-cy="dashboard-summary"]').should('not.exist');
          cy.get('[data-cy="dashboard-student-row"]').should('not.exist');
          cy.wrap(null).should(() =>
            expect(releaseDashboardError).to.be.a('function'),
          );
          cy.then(() => releaseDashboardError!());
        }
        cy.wait(`@dashboardGate${retried}`).then(({ response }) => {
          expect(response!.statusCode).to.equal(cycle === 0 ? 200 : 403);
          if (cycle === 0)
            expect(response!.body.data.summary).to.include({
              completed: c.oracle.completed,
              required: c.oracle.required,
            });
        });
        if (cycle === 0) {
          cy.get('[data-cy="dashboard-summary"]').should(
            'contain.text',
            `${c.oracle.completed}/${c.oracle.required}`,
          );
          cy.get('[data-cy="dashboard-student-row"]').should('have.length', 50);
          cy.get(
            '[data-cy="dashboard-summary"] [data-cy="dashboard-period-attempts"]',
          ).should('have.text', String(c.oracle.attempts));
        } else {
          cy.contains('[role="alert"]', 'Acceso no permitido').should(
            'be.visible',
          );
          cy.get('[data-cy="dashboard-summary"]').should('not.exist');
          cy.get('[data-cy="dashboard-student-row"]').should('not.exist');
          cy.get('[data-cy="dashboard-signals"]').should('not.exist');
          cy.get('body').should(
            'not.contain.text',
            `${c.oracle.completed}/${c.oracle.required}`,
          );
        }
        cy.then(() => {
          for (const endpoint of ['organization', 'dashboard'])
            for (const stage of [blocked, retried])
              expect(requestCounts[`${endpoint}Gate${stage}`]).to.equal(1);
        });
      }
      cy.then(() => {
        failureChecksActive = false;
      });
      let release: (() => void) | undefined;
      let heldSignal: AbortSignal | null | undefined;
      let hold = true;
      visitAs(c.teacher, route(c, 'dashboard'), (window) => {
        const original = window.fetch.bind(window);
        window.fetch = (input, init) =>
          original(input, init).then((response) => {
            if (
              hold &&
              String(input).includes('/dashboard?') &&
              String(input).includes(c.activityIds[1]!) &&
              response.ok
            ) {
              hold = false;
              heldSignal = init?.signal;
              return new Promise<Response>((resolve) => {
                release = () => resolve(response);
                releases.push(release);
              });
            }
            return response;
          });
      });
      cy.get('[data-cy="dashboard-summary"]').should('contain.text', '1/360');
      cy.get('#dashboard-activity').select(c.activityIds[1]!);
      apply();
      cy.wrap(null).should(() => expect(release).to.be.a('function'));
      cy.get('[data-cy="dashboard-summary"]').should('not.exist');
      cy.get('#dashboard-activity').select(c.activityIds[0]!);
      apply();
      cy.get('[data-cy="dashboard-summary"]').should('contain.text', '1/180');
      cy.then(() => {
        expect(heldSignal?.aborted).to.equal(true);
        release!();
      });
      cy.get('[data-cy="dashboard-summary"]').should('contain.text', '1/180');
      cy.then(() => {
        hold = true;
        release = undefined;
      });
      cy.get('#dashboard-activity').select(c.activityIds[1]!);
      apply();
      cy.wrap(null).should(() => expect(release).to.be.a('function'));
      cy.contains('button', /^Cerrar sesión$/).click();
      cy.location('pathname').should('equal', '/acceso');
      cy.wrap(null).should(() => expect(heldSignal?.aborted).to.equal(true));
      cy.get('#email').type(c.admin.user.email!, { log: false });
      cy.env(['fixturePassword'], { log: false }).then(({ fixturePassword }) =>
        cy.get('#password').type(String(fixturePassword), {
          log: false,
          parseSpecialCharSequences: false,
        }),
      );
      cy.contains('button', /^Iniciar sesión$/).click();
      cy.location('pathname').should('equal', '/inicio');
      cy.then(() => release!());
      cy.get('[data-cy="dashboard-summary"]').should('not.exist');
      cy.visit(route(c, 'dashboard'));
      cy.get('[role="alert"]').should('be.visible');
      cy.get('[data-cy="dashboard-student-row"]').should('not.exist');
      // Logout revoked this JWT; restoring membership must not revive it.
      visitAs(c.teacher, route(c, 'dashboard'));
      cy.get('[role="alert"]').should('be.visible');
      cy.get('[data-cy="dashboard-summary"]').should('not.exist');
      cy.task<Session>('identity:login', 'TEACHER', { log: false }).then(
        (teacher) => {
          const renewed = { ...c, teacher };
          ready(renewed);
          cy.task(
            'phase:revoke',
            { organizationId: c.organizationId, actor: 'teacher' },
            { log: false },
          );
          visitAs(teacher, route(c, 'dashboard'));
          cy.get('[role="alert"]').should('be.visible');
          cy.get('[data-cy="dashboard-summary"]').should('not.exist');
          cy.task(
            'phase:revoke',
            {
              organizationId: c.organizationId,
              actor: 'teacher',
              restore: true,
            },
            { log: false },
          );
          ready(renewed);
        },
      );
    });
  });

